const o = await window.overview();
const a = await show({read:"window.overview", from:"workstreams", form:"table", columns:["name","size","moved","status","signals"], caption:"Your workstreams"});
const b = await show({read:"window.overview", from:"people.rows", form:"bars", label:"name", value:"inProgress", caption:"Work in progress by person"});
return {a,b};

